import { execFileSync } from "node:child_process";
import type { StageProviderAdapter } from "./types";
function run(projectDirectory: string, args: string[], environment: Record<string, string> = {}): string { return execFileSync("docker", args, { cwd: projectDirectory, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], env: { ...process.env, ...environment } }); }
export const dockerStageAdapter: StageProviderAdapter = { id: "docker", capabilities: { create: true, inspect: true, update: true, destroy: true }, create(input) { run(input.projectDirectory, ["compose", "-p", input.resourceId, "up", "-d", "--build"], input.environment); return { resourceId: input.resourceId, url: process.env.LAUNCHSTACK_PREVIEW_URL }; }, inspect(input) { try { const output = run(input.projectDirectory, ["compose", "-p", input.resourceId, "ps", "--format", "json"]).trim(); if (!output) return { exists: false }; const records = output.split(/\r?\n/).flatMap((line) => { try { const value = JSON.parse(line); return Array.isArray(value) ? value : [value]; } catch { return []; } }); if (!records.length) return { exists: false }; const running = records.every((record) => record && typeof record === "object" && String((record as { State?: unknown }).State).toLowerCase() === "running"); return { exists: true, status: running ? "running" : "degraded" }; } catch { return { exists: false }; } }, destroy(input) { run(input.projectDirectory, ["compose", "-p", input.resourceId, "down", "--remove-orphans", "--volumes"], input.environment); } };
