import { Command } from "commander";
import { applyModuleGeneration, parseFieldSpec, planModuleGeneration } from "../generator/module";
function configure(kind: "module" | "resource"): Command { const command = new Command(kind).argument("<name>").option("-d, --directory <path>").option("--field <name:type...>", "Repeat for resource fields", (value: string, previous: string[]) => [...previous, value], []).option("--dry-run").option("--json"); if (kind === "resource") command.option("--crud", "Generate CRUD endpoints (default for resources)"); return command.action((name: string, options: { directory?: string; field: string[]; dryRun?: boolean; json?: boolean; crud?: boolean }) => { try { if (kind === "module" && options.field.length) throw new Error("--field is only supported by generate resource."); const plan = planModuleGeneration({ projectDirectory: options.directory ?? process.cwd(), kind, name, fields: options.field.map(parseFieldSpec) }); if (!options.dryRun) applyModuleGeneration(plan); const output = { dryRun: Boolean(options.dryRun), kind, name, crud: kind === "resource", files: plan.files, migrationCommand: plan.migrationCommand }; if (options.json) console.log(JSON.stringify(output, null, 2)); else { for (const path of plan.files) console.log(`${options.dryRun ? "PLAN" : "CREATE"} ${path}`); if (plan.migrationCommand) console.log(`Next: ${plan.migrationCommand}`); } } catch (error) { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 1; } }); }
export const generateCommand = new Command("generate").description("Generate architecture-aware modules and resources").addCommand(configure("module")).addCommand(configure("resource"));
