import { Command } from "commander";
import { createDevPlan, DevOrchestrator, selectDevPlan } from "../dev/orchestrator";
export const devCommand = new Command("dev").description("Start LaunchStack-managed local development services").option("-d, --directory <path>").option("--service <id>", "Start one service plus its dependencies").option("--no-migrate", "Skip the migration process").option("--json").option("--readiness-timeout <ms>", "Readiness timeout", "30000").action(async (options: { directory?: string; service?: string; migrate: boolean; json?: boolean; readinessTimeout: string }) => { try { const plan = selectDevPlan(createDevPlan(options.directory ?? process.cwd()), { service: options.service, noMigrate: options.migrate === false }); if (options.json) { console.log(JSON.stringify(plan, null, 2)); return; } const timeoutMs = Number.parseInt(options.readinessTimeout, 10); if (!Number.isInteger(timeoutMs) || timeoutMs < 1000 || timeoutMs > 300_000) throw new Error("--readiness-timeout must be between 1000 and 300000 milliseconds."); const orchestrator = new DevOrchestrator(plan); let stopping = false; const stop = async () => { if (stopping) return; stopping = true; await orchestrator.stop(); }; process.once("SIGINT", () => void stop().then(() => { process.exitCode = 130; })); process.once("SIGTERM", () => void stop().then(() => { process.exitCode = 143; })); await orchestrator.start({ readinessTimeoutMs: timeoutMs }); console.log("Development services are ready. Press Ctrl+C to stop LaunchStack-owned processes."); } catch (error) { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 1; } });
