import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { Command } from "commander";
import { generateTypeScriptClient, loadOpenApiSource, type ClientTarget } from "../client/generate";
const TARGETS = new Set<ClientTarget>(["typescript", "react", "react-native"]);
export const clientGenerateCommand = new Command("generate").description("Generate a typed client from an OpenAPI JSON document").option("--schema <path-or-url>", "OpenAPI JSON file or HTTPS endpoint", "./openapi.json").option("--target <target>", "typescript, react, or react-native", "typescript").option("-o, --output <path>", "Output TypeScript file", "./src/generated/launchstack-client.ts").option("--check", "Fail if output differs without writing").action(async (options: { schema: string; target: string; output: string; check?: boolean }) => { try { if (!TARGETS.has(options.target as ClientTarget)) throw new Error(`Unsupported client target: ${options.target}`); const source = /^https?:\/\//i.test(options.schema) ? options.schema : resolve(options.schema); if (/^http:\/\//i.test(source)) throw new Error("Remote OpenAPI schemas must use HTTPS."); const generated = generateTypeScriptClient(await loadOpenApiSource(source), options.target as ClientTarget); const output = resolve(options.output); if (options.check) { if (!existsSync(output) || readFileSync(output, "utf8") !== generated) { console.error(`Generated client is stale: ${output}`); process.exitCode = 1; return; } console.log(`Generated client is current: ${output}`); return; } mkdirSync(dirname(output), { recursive: true }); writeFileSync(output, generated, "utf8"); console.log(`Generated ${options.target} client: ${output}`); } catch (error) { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 1; } });
export const clientCommand = new Command("client").description("Generate and verify typed API clients").addCommand(clientGenerateCommand);
